//! 👁️ Derives bounded borrowed JSON projection directly from value wire declarations.
use proc_macro2::TokenStream;
use quote::{format_ident,quote};
use syn::{parse_quote,Attribute,Data,DeriveInput,Fields,Generics,LitStr,Path,Type};
#[derive(Default)]
struct Attrs{rename:Option<String>,all:Option<String>,fields:Option<String>,tag:Option<String>,content:Option<String>,transparent:bool,skip:bool,flatten:bool,skip_if:Option<Path>,with:Option<Path>,json_crate:Option<Path>,protocol:Option<Path>}
fn attrs(values:&[Attribute])->syn::Result<Attrs>{let mut out=Attrs::default();for attr in values{if attr.path().is_ident("borrowed_json"){attr.parse_nested_meta(|meta|{let value=meta.value()?.parse::<LitStr>()?;if meta.path.is_ident("crate"){out.json_crate=Some(value.parse()?)}else if meta.path.is_ident("protocol"){out.protocol=Some(value.parse()?)}else{return Err(meta.error("borrowed_json supports crate and protocol paths"))}Ok(())})?;}else if attr.path().is_ident("value"){attr.parse_nested_meta(|meta|{let name=meta.path.get_ident().map(ToString::to_string).unwrap_or_default();if meta.input.peek(syn::Token![=]){let value=meta.value()?.parse::<LitStr>()?;match name.as_str(){"rename"=>out.rename=Some(value.value()),"rename_all"=>out.all=Some(value.value()),"rename_all_fields"=>out.fields=Some(value.value()),"tag"=>out.tag=Some(value.value()),"content"=>out.content=Some(value.value()),"skip_serializing_if"=>out.skip_if=Some(value.parse()?),"with"=>out.with=Some(value.parse()?),_=>{}}}else{match name.as_str(){"transparent"=>out.transparent=true,"skip"|"skip_serializing"=>out.skip=true,"flatten"=>out.flatten=true,_=>{}}}Ok(())})?;}}Ok(out)}
fn rename(name:&str,rule:Option<&str>,field:bool)->syn::Result<String>{Ok(match rule.unwrap_or(""){
 ""=>name.into(),"lowercase"=>name.to_lowercase(),"UPPERCASE"=>name.to_uppercase(),"snake_case"=>if field{name.into()}else{words(name).join("_")},"SCREAMING_SNAKE_CASE"=>if field{name.to_uppercase()}else{words(name).join("_").to_uppercase()},"kebab-case"=>if field{name.replace('_',"-")}else{words(name).join("-")},"SCREAMING-KEBAB-CASE"=>if field{name.replace('_',"-").to_uppercase()}else{words(name).join("-").to_uppercase()},"camelCase"=>{if field{let mut parts=name.split('_');let mut out=parts.next().unwrap_or("").to_string();for part in parts{let mut chars=part.chars();if let Some(first)=chars.next(){out.extend(first.to_uppercase());out.extend(chars)}}out}else{let mut chars=name.chars();let mut out=String::new();if let Some(first)=chars.next(){out.extend(first.to_lowercase());out.extend(chars)}out}},"PascalCase"=>{if field{name.split('_').map(|part|{let mut chars=part.chars();let mut out=String::new();if let Some(first)=chars.next(){out.extend(first.to_uppercase());out.extend(chars)}out}).collect()}else{name.into()}},other=>return Err(syn::Error::new(proc_macro2::Span::call_site(),format!("unsupported borrowed JSON casing {other}")))})}
fn words(name:&str)->Vec<String>{let mut out=Vec::<String>::new();for c in name.chars(){if c.is_uppercase()||out.is_empty(){out.push(String::new())}out.last_mut().unwrap().extend(c.to_lowercase())}out}
struct Field{key:String,value:TokenStream,ty:Type,attrs:Attrs}
fn fields(source:&Fields,rule:Option<&str>,enum_fields:bool)->syn::Result<(Vec<Field>,TokenStream)>{if source.len()>32{return Err(syn::Error::new_spanned(source,"borrowed JSON record exceeds 32 statically bounded fields"))}let mut output=Vec::new();let mut bindings=Vec::new();for(index,field)in source.iter().enumerate(){let a=attrs(&field.attrs)?;if a.flatten{return Err(syn::Error::new_spanned(field,"borrowed JSON flatten requires an explicit bounded projection owner"))}let binding=format_ident!("__json_field_{index}");let value=if enum_fields{quote!(#binding)}else if let Some(name)=&field.ident{quote!(&self.#name)}else{let index=syn::Index::from(index);quote!(&self.#index)};if enum_fields{bindings.push(if let Some(name)=&field.ident{quote!(#name:#binding)}else{quote!(#binding)});}let key=a.rename.clone().unwrap_or(rename(&field.ident.as_ref().map(ToString::to_string).unwrap_or(index.to_string()),rule,true)?);if !a.skip{output.push(Field{key,value,ty:field.ty.clone(),attrs:a})}}let pattern=match source{Fields::Named(_)=>quote!({#(#bindings,)*}),Fields::Unnamed(_)=>quote!((#(#bindings,)*)),Fields::Unit=>quote!()};Ok((output,pattern))}
fn contains_ident(tokens:TokenStream,name:&syn::Ident)->bool{tokens.into_iter().any(|token|match token{proc_macro2::TokenTree::Ident(ident)=>ident==*name,proc_macro2::TokenTree::Group(group)=>contains_ident(group.stream(),name),_=>false})}
fn bind(generics:&mut Generics,fields:&[Field],trait_path:&Path){let names=generics.type_params().map(|p|p.ident.clone()).collect::<Vec<_>>();for name in names{if fields.iter().any(|field|{let ty=&field.ty;field.attrs.with.is_none()&&contains_ident(quote!(#ty),&name)}){generics.make_where_clause().predicates.push(parse_quote!(#name:#trait_path));}}}
fn enabled(field:&Field)->TokenStream{let value=&field.value;if let Some(skip)=&field.attrs.skip_if{quote!(!#skip(#value))}else{quote!(true)}}
fn reference(field:&Field,path:&Path,protocol:Option<&Path>)->TokenStream{let value=&field.value;if let Some(with)=&field.attrs.with{quote!(#with::borrow_json(#value,context)?)}else if let Some(protocol)=protocol{let ty=&field.ty;quote!(#path::JsonBorrowNode::Projected(#value as &dyn std::any::Any, &<#ty as #protocol>::JSON,0))}else{quote!(#path::json_borrow_native(#value))}}
fn body(fields:&[Field],named:bool,transparent:bool,path:&Path,protocol:Option<&Path>)->(TokenStream,TokenStream,TokenStream){
 if transparent{let field=&fields[0];let reference=reference(field,path,protocol);return(quote!({let reference=#reference;reference.project_node(context)}),quote!({let reference=#reference;reference.project_child(index,context)}),quote!({let reference=#reference;reference.project_key(index,context)}))}
 let enableds=fields.iter().map(enabled).collect::<Vec<_>>();let kind=if named{quote!(#path::JsonWriteNode::Object)}else{quote!(#path::JsonWriteNode::Array)};
 let node=quote!({let mut length=0usize;#(if #enableds{length+=1;})*Ok(#kind(length))});
 let children=fields.iter().map(|field|{let enabled=enabled(field);let reference=reference(field,path,protocol);quote!(if #enabled{if remaining==0{return Ok(#reference)}remaining-=1;})}).collect::<Vec<_>>();
 let child=quote!({let mut remaining=index;#(#children)*let _=remaining;Err(#path::json_borrow_absent())});
 let keys=fields.iter().map(|field|{let enabled=enabled(field);let key=&field.key;quote!(if #enabled{if remaining==0{return Ok(#key)}remaining-=1;})}).collect::<Vec<_>>();
 let key=if named{quote!({let mut remaining=index;#(#keys)*let _=remaining;Err(#path::json_borrow_absent())})}else{quote!(Err(#path::json_borrow_absent()))};(node,child,key)
}
fn edge(input:&DeriveInput,a:&Attrs,path:&Path,protocol:Option<&Path>)->syn::Result<TokenStream>{
 let default=quote!(Ok(#path::JsonWriteEdge{child:index,cursor:0}));
 Ok(match &input.data{
  Data::Struct(data)if a.transparent=>{let(f,_)=fields(&data.fields,a.all.as_deref(),false)?;let reference=reference(&f[0],path,protocol);quote!(if mode==0{let reference=#reference;reference.project_edge(index,cursor,context)}else{Err(#path::json_borrow_absent())})},
  Data::Struct(_)=>quote!(if mode==0{#default}else{Err(#path::json_borrow_absent())}),
  Data::Enum(data)=>{let mut arms=Vec::new();for variant in &data.variants{let va=attrs(&variant.attrs)?;let(f,pattern)=fields(&variant.fields,va.all.as_deref().or(a.fields.as_deref()),true)?;let name=&variant.ident;let transparent=matches!(&variant.fields,Fields::Unnamed(_))&&f.len()==1&&(a.tag.is_none()||a.content.is_some());let internal=matches!(&variant.fields,Fields::Unnamed(_))&&f.len()==1&&a.tag.is_some()&&a.content.is_none();let value=if internal{let reference=reference(&f[0],path,protocol);quote!(if mode!=0{Err(#path::json_borrow_absent())}else if index==0{#default}else{let reference=#reference;let edge=reference.project_edge(index-1,cursor,context)?;Ok(#path::JsonWriteEdge{child:edge.child.checked_add(1).ok_or_else(#path::json_borrow_absent)?,cursor:edge.cursor})})}else if transparent{let reference=reference(&f[0],path,protocol);quote!(match mode{0=>#default,1=>{let reference=#reference;reference.project_edge(index,cursor,context)},_=>Err(#path::json_borrow_absent())})}else{quote!(#default)};arms.push(quote!(Self::#name #pattern=>{#value}));}quote!(match self{#(#arms,)*})},
  Data::Union(_)=>return Err(syn::Error::new_spanned(input,"borrowed unions have no traversal edges")),
 })
}
pub fn expand(input:&DeriveInput)->syn::Result<TokenStream>{
 let a=attrs(&input.attrs)?;let path=a.json_crate.clone().unwrap_or(parse_quote!(::semio_framework_pack_json));let protocol=a.protocol.as_ref();let trait_path:Path=protocol.cloned().unwrap_or(parse_quote!(#path::JsonNativeBorrow));let self_body=if let Some(protocol)=protocol{quote!(#path::JsonBorrowNode::Projected(self as &dyn std::any::Any,&<Self as #protocol>::JSON,1))}else{quote!(#path::JsonBorrowNode::Native(self,1))};let mut generics=input.generics.clone();let name=&input.ident;
 let(node,child,key)=match &input.data{
  Data::Struct(data)=>{let(f,_)=fields(&data.fields,a.all.as_deref(),false)?;if a.transparent&&f.len()!=1{return Err(syn::Error::new_spanned(input,"borrowed transparent owner requires one emitted field"))}bind(&mut generics,&f,&trait_path);let(n,c,k)=body(&f,matches!(&data.fields,Fields::Named(_)),a.transparent,&path,protocol);(quote!(if mode==0{#n}else{Err(#path::json_borrow_absent())}),quote!(if mode==0{#c}else{Err(#path::json_borrow_absent())}),quote!(if mode==0{#k}else{Err(#path::json_borrow_absent())}))},
  Data::Enum(data)=>{if a.transparent{return Err(syn::Error::new_spanned(input,"borrowed enums cannot be transparent"))}let(mut nodes,mut children,mut keys)=(Vec::new(),Vec::new(),Vec::new());for variant in &data.variants{let va=attrs(&variant.attrs)?;if va.skip{return Err(syn::Error::new_spanned(variant,"borrowed skipped variants require an explicit refusal owner"))}let variant_name=&variant.ident;let tag=va.rename.clone().unwrap_or(rename(&variant.ident.to_string(),a.all.as_deref(),false)?);let(f,pattern)=fields(&variant.fields,va.all.as_deref().or(a.fields.as_deref()),true)?;bind(&mut generics,&f,&trait_path);let unit=matches!(&variant.fields,Fields::Unit);let transparent=matches!(&variant.fields,Fields::Unnamed(_))&&f.len()==1;let(n,c,k)=if unit{(quote!(Ok(#path::JsonWriteNode::Null)),quote!(Err(#path::json_borrow_absent())),quote!(Err(#path::json_borrow_absent())))}else{body(&f,matches!(&variant.fields,Fields::Named(_)),transparent,&path,protocol)};
   let(n,c,k)=if let Some(tag_key)=&a.tag{if let Some(content)=&a.content{let count=if unit{1usize}else{2usize};(quote!(match mode{0=>Ok(#path::JsonWriteNode::Object(#count)),1=>#n,_=>Err(#path::json_borrow_absent())}),quote!(match(mode,index){(0,0)=>Ok(#path::JsonBorrowNode::Scalar(#path::JsonWriteNode::String(#tag))),(0,1)if!#unit=>Ok(#self_body),(1,index)=>#c,_=>Err(#path::json_borrow_absent())}),quote!(match(mode,index){(0,0)=>Ok(#tag_key),(0,1)if!#unit=>Ok(#content),(1,index)=>#k,_=>Err(#path::json_borrow_absent())}))}else{if !unit&&!matches!(&variant.fields,Fields::Named(_))&&!transparent{return Err(syn::Error::new_spanned(variant,"internally tagged borrowed tuple requires one object payload"))}(quote!(if mode!=0{Err(#path::json_borrow_absent())}else{if #unit{return Ok(#path::JsonWriteNode::Object(1))}let body:Result<#path::JsonWriteNode<'_>,#path::JsonBorrowError>=#n;let body=body?;let #path::JsonWriteNode::Object(length)=body else{return Err(#path::json_borrow_absent())};Ok(#path::JsonWriteNode::Object(length.checked_add(1).ok_or_else(#path::json_borrow_absent)?))}),quote!(if mode!=0{Err(#path::json_borrow_absent())}else if index==0{Ok(#path::JsonBorrowNode::Scalar(#path::JsonWriteNode::String(#tag)))}else{let index=index-1;#c}),quote!(if mode!=0{Err(#path::json_borrow_absent())}else if index==0{Ok(#tag_key)}else{let index=index-1;#k}))}}else if unit{(quote!(if mode==0{Ok(#path::JsonWriteNode::String(#tag))}else{Err(#path::json_borrow_absent())}),quote!(Err(#path::json_borrow_absent())),quote!(Err(#path::json_borrow_absent())))}else{(quote!(match mode{0=>Ok(#path::JsonWriteNode::Object(1)),1=>#n,_=>Err(#path::json_borrow_absent())}),quote!(match(mode,index){(0,0)=>Ok(#self_body),(1,index)=>#c,_=>Err(#path::json_borrow_absent())}),quote!(match(mode,index){(0,0)=>Ok(#tag),(1,index)=>#k,_=>Err(#path::json_borrow_absent())}))};nodes.push(quote!(Self::#variant_name #pattern=>{#n}));children.push(quote!(Self::#variant_name #pattern=>{#c}));keys.push(quote!(Self::#variant_name #pattern=>{#k}));}(quote!(match self{#(#nodes,)*}),quote!(match self{#(#children,)*}),quote!(match self{#(#keys,)*}))},
  Data::Union(_)=>return Err(syn::Error::new_spanned(input,"borrowed unions have no closed wire projection")),
 };
 let edge=edge(input,&a,&path,protocol)?;let(impl_generics,type_generics,where_clause)=generics.split_for_impl();Ok(quote!(impl #impl_generics #trait_path for #name #type_generics #where_clause{
  fn json_node<'__json>(&'__json self,mode:u8,context:&'__json dyn #path::JsonBorrowContext)->Result<#path::JsonWriteNode<'__json>,#path::JsonBorrowError>{#node}
  fn json_child<'__json>(&'__json self,mode:u8,index:usize,context:&'__json dyn #path::JsonBorrowContext)->Result<#path::JsonBorrowNode<'__json>,#path::JsonBorrowError>{#child}
  fn json_key<'__json>(&'__json self,mode:u8,index:usize,context:&'__json dyn #path::JsonBorrowContext)->Result<&'__json str,#path::JsonBorrowError>{#key}
  fn json_edge(&self,mode:u8,index:usize,cursor:usize,context:&dyn #path::JsonBorrowContext)->Result<#path::JsonWriteEdge,#path::JsonBorrowError>{#edge}
 }))
}

pub fn codec(input:&DeriveInput)->syn::Result<TokenStream>{
 if attrs(&input.attrs)?.protocol.is_none(){return Err(syn::Error::new_spanned(input,"an external native JSON codec requires its local extension protocol"))}
 let name=&input.ident;let proof=match &input.data{
  Data::Struct(data)=>{let names=data.fields.iter().enumerate().map(|(i,f)|f.ident.clone().unwrap_or(format_ident!("field_{i}"))).collect::<Vec<_>>();let types=data.fields.iter().map(|f|&f.ty);let pattern=match &data.fields{Fields::Named(_)=>quote!(#name{#(#names,)*}),Fields::Unnamed(_)=>quote!(#name(#(#names,)*)),Fields::Unit=>quote!(#name)};quote!(const _:for<'__json>fn(&'__json #name)->(#(&'__json #types,)*)=|#pattern|(#(#names,)*);)},
  Data::Enum(data)=>{let variants=data.variants.iter().map(|variant|{let v=&variant.ident;let names=variant.fields.iter().enumerate().map(|(i,f)|f.ident.clone().unwrap_or(format_ident!("field_{i}"))).collect::<Vec<_>>();let types=variant.fields.iter().map(|f|&f.ty);let pattern=match &variant.fields{Fields::Named(_)=>quote!(#name::#v{#(#names,)*}),Fields::Unnamed(_)=>quote!(#name::#v(#(#names,)*)),Fields::Unit=>quote!(#name::#v)};quote!(#pattern=>{let _:(#(&#types,)*)=(#(#names,)*);})});quote!(const _:fn(&#name)=|value|{match value{#(#variants,)*}};)},
  Data::Union(_)=>return Err(syn::Error::new_spanned(input,"external borrowed unions have no wire contract")),
 };let expanded=expand(input)?;Ok(quote!(#proof #expanded))
}
